CREATE DATABASE IF NOT EXISTS ist_demandes CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE ist_demandes;
CREATE TABLE ecoles(id TINYINT AUTO_INCREMENT PRIMARY KEY,code VARCHAR(10) UNIQUE,nom VARCHAR(120));
CREATE TABLE roles(id TINYINT AUTO_INCREMENT PRIMARY KEY,code VARCHAR(30) UNIQUE,libelle VARCHAR(80));
CREATE TABLE utilisateurs(id INT AUTO_INCREMENT PRIMARY KEY,nom VARCHAR(80),prenoms VARCHAR(120),identifiant VARCHAR(40) UNIQUE,mot_de_passe VARCHAR(255),service VARCHAR(80),actif TINYINT(1) DEFAULT 1,cree_le DATETIME DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE utilisateur_role(utilisateur_id INT,role_id TINYINT,PRIMARY KEY(utilisateur_id,role_id),FOREIGN KEY(utilisateur_id) REFERENCES utilisateurs(id),FOREIGN KEY(role_id) REFERENCES roles(id));
CREATE TABLE etudiants(id INT AUTO_INCREMENT PRIMARY KEY,nom VARCHAR(80),prenoms VARCHAR(120),date_naissance DATE,lieu_naissance VARCHAR(80),telephone VARCHAR(40),email VARCHAR(120),adresse VARCHAR(160),ecole_id TINYINT,mention VARCHAR(100),parcours VARCHAR(100),promotion VARCHAR(20) NULL,diplome_vise ENUM('DTS','DTSS','INGENIORAT') NULL,FOREIGN KEY(ecole_id) REFERENCES ecoles(id),INDEX(nom,prenoms));
CREATE TABLE types_demande(id TINYINT AUTO_INCREMENT PRIMARY KEY,code VARCHAR(30) UNIQUE,libelle VARCHAR(80),delai_cible_jours INT NULL);
CREATE TABLE tarifs(id INT AUTO_INCREMENT PRIMARY KEY,type_demande_id TINYINT,niveau_diplome ENUM('DTS','DTSS','INGENIORAT') NULL,montant INT,montant_retard INT NULL,date_debut DATE,date_fin DATE NULL,FOREIGN KEY(type_demande_id) REFERENCES types_demande(id));
CREATE TABLE pieces_requises(id INT AUTO_INCREMENT PRIMARY KEY,type_demande_id TINYINT,libelle VARCHAR(160),obligatoire TINYINT(1) DEFAULT 1,FOREIGN KEY(type_demande_id) REFERENCES types_demande(id));
CREATE TABLE demandes(id INT AUTO_INCREMENT PRIMARY KEY,numero VARCHAR(20) UNIQUE,type_demande_id TINYINT,etudiant_id INT,niveau VARCHAR(10) NULL,annee_universitaire VARCHAR(9) NULL,date_depot DATETIME DEFAULT CURRENT_TIMESTAMP,numero_arrivee VARCHAR(20) NULL,
 statut ENUM('ENREGISTREE','PAIEMENT_VERIFIE','RECEVABLE','AFFECTEE','EN_TRAITEMENT','EN_ATTENTE_ETUDIANT','EN_SIGNATURE','TRAITEE','LIVREE','REFUSEE') DEFAULT 'ENREGISTREE',
 agent_id INT NULL,date_affectation DATETIME NULL,date_fin_traitement DATETIME NULL,date_reponse DATETIME NULL,date_livraison DATETIME NULL,mode_retrait ENUM('ETUDIANT','MANDATAIRE') NULL,observation TEXT NULL,cree_par INT NULL,
 FOREIGN KEY(type_demande_id) REFERENCES types_demande(id),FOREIGN KEY(etudiant_id) REFERENCES etudiants(id),FOREIGN KEY(agent_id) REFERENCES utilisateurs(id),INDEX(statut),INDEX(etudiant_id,type_demande_id,niveau,annee_universitaire));
CREATE TABLE paiements(id INT AUTO_INCREMENT PRIMARY KEY,demande_id INT,type_justificatif ENUM('RECU_IST','BORDEREAU_BANCAIRE'),numero VARCHAR(30),annee SMALLINT,date_paiement DATE,montant_paye INT,montant_attendu INT NULL,motif VARCHAR(120),saisi_par INT NULL,UNIQUE(type_justificatif,numero,annee),FOREIGN KEY(demande_id) REFERENCES demandes(id));
CREATE TABLE pieces_fournies(id INT AUTO_INCREMENT PRIMARY KEY,demande_id INT,piece_requise_id INT,fournie TINYINT(1) DEFAULT 0,date_fourniture DATE NULL,observation VARCHAR(160) NULL,FOREIGN KEY(demande_id) REFERENCES demandes(id),FOREIGN KEY(piece_requise_id) REFERENCES pieces_requises(id));
CREATE TABLE historique_statut(id INT AUTO_INCREMENT PRIMARY KEY,demande_id INT,ancien_statut VARCHAR(30) NULL,nouveau_statut VARCHAR(30),date_heure DATETIME DEFAULT CURRENT_TIMESTAMP,utilisateur_id INT NULL,commentaire VARCHAR(200) NULL,FOREIGN KEY(demande_id) REFERENCES demandes(id));
CREATE TABLE quitus(id INT AUTO_INCREMENT PRIMARY KEY,numero VARCHAR(20),annee SMALLINT,etudiant_id INT,date_quitus DATE NULL,signe_responsable TINYINT(1) DEFAULT 0,signe_daf TINYINT(1) DEFAULT 0,en_retard TINYINT(1) DEFAULT 0,frais_retard INT DEFAULT 0,UNIQUE(etudiant_id,annee),FOREIGN KEY(etudiant_id) REFERENCES etudiants(id));
CREATE TABLE quitus_visas(id INT AUTO_INCREMENT PRIMARY KEY,quitus_id INT,position TINYINT,service VARCHAR(100),observation VARCHAR(160) NULL,responsable VARCHAR(100) NULL,date_visa DATE NULL,valide TINYINT(1) DEFAULT 0,FOREIGN KEY(quitus_id) REFERENCES quitus(id));
CREATE TABLE attestations(id INT AUTO_INCREMENT PRIMARY KEY,numero VARCHAR(20) UNIQUE,etudiant_id INT,diplome ENUM('DTS','DTSS','INGENIORAT'),date_deliberation DATE NULL,date_provisoire DATE NULL,date_signature_titulaire DATE NULL,date_signature_directeur DATE NULL,date_signature_dg DATE NULL,version ENUM('PROVISOIRE','ORIGINALE') DEFAULT 'PROVISOIRE',date_retrait DATE NULL,FOREIGN KEY(etudiant_id) REFERENCES etudiants(id));
CREATE TABLE journal_audit(id INT AUTO_INCREMENT PRIMARY KEY,utilisateur_id INT NULL,action VARCHAR(60),detail VARCHAR(255) NULL,date_heure DATETIME DEFAULT CURRENT_TIMESTAMP);
