CREATE TABLE IF NOT EXISTS parcours(id INT AUTO_INCREMENT PRIMARY KEY,code VARCHAR(20) UNIQUE,libelle VARCHAR(120) NULL,ecole_id TINYINT,mention VARCHAR(40),niveaux VARCHAR(30) DEFAULT 'L1,L2,L3,M1,M2',FOREIGN KEY(ecole_id) REFERENCES ecoles(id));
ALTER TABLE demandes ADD COLUMN parcours VARCHAR(20) NULL;
INSERT INTO parcours(code,libelle,ecole_id,mention,niveaux) SELECT v.c,v.l,e.id,v.m,v.n FROM ecoles e JOIN (
 SELECT 'EGI' k,'MEEM' c,'Maintenance des Équipements Électromécaniques' l,'MME' m,'L1,L2,L3,M1,M2' n UNION ALL SELECT 'EGI','MEFT','Maintenance en Équipements Frigorifiques et Thermiques','MME','L1,L2,L3,M1,M2'
 UNION ALL SELECT 'EGI','MSA','Maintenance en Systèmes Automatisés','MME','L1,L2,L3,M1,M2' UNION ALL SELECT 'EGI','SERA','Systèmes à Énergies Renouvelables et Alternatives','MME','L1,L2,L3,M1,M2'
 UNION ALL SELECT 'EGI','MURE',NULL,'MME','L1,L2,L3,M1,M2' UNION ALL SELECT 'EGI','NTE','Nouvelle Technologie de l''Électricité','MME','L1,L2,L3,M1,M2' UNION ALL SELECT 'EGI','TAM','Techniques Avancées de Maintenance','MME','L1,L2,L3,M1,M2'
 UNION ALL SELECT 'EGI','RT','Réseaux et Télécommunications','TC','L1,L2,L3,M1,M2' UNION ALL SELECT 'EGI','TIM','Technologie de l''Information et Multimédia','TC','L1,L2,L3,M1,M2'
 UNION ALL SELECT 'EGI','ADR','Administration des Réseaux','TC','L1,L2,L3,M1,M2' UNION ALL SELECT 'EGI','IRM','Ingénierie des Réseaux Mobiles','TC','L3' UNION ALL SELECT 'EGI','ICE','Ingénierie des Communications Électroniques','TC','L1,L2,L3,M1,M2'
 UNION ALL SELECT 'EGMCS','COM','Commerce','CS','L1,L2,L3,M1,M2' UNION ALL SELECT 'EGMCS','TGH','Tourisme et Gestion Hôtelière','CS','L1,L2,L3,M1,M2' UNION ALL SELECT 'EGMCS','TCI','Transit et Commerce International','CS','L1,L2,L3,M1,M2'
 UNION ALL SELECT 'EGMCS','DPT','Développement de Produits Touristiques','CS','L3' UNION ALL SELECT 'EGMCS','TBA','Technique Bancaire et Assurance','FBA','L1,L2,L3,M1,M2' UNION ALL SELECT 'EGMCS','GFC','Gestion Financière et Comptable','FBA','L1,L2,L3,M1,M2'
 UNION ALL SELECT 'EGMCS','CGC','Conseiller Gestionnaire de Clientèle','FBA','L1,L2,L3,M1,M2' UNION ALL SELECT 'EGMCS','CCA','Comptabilité Contrôle et Audit','FBA','L3' UNION ALL SELECT 'EGMCS','MEO','Management des Entreprises et des Organisations','Management','M1,M2'
 UNION ALL SELECT 'EGCGN','TP',NULL,'GC','L1,L2,L3,M1,M2' UNION ALL SELECT 'EGCGN','BAT',NULL,'GC','L1,L2,L3,M1,M2' UNION ALL SELECT 'EGCGN','CCI',NULL,'GC','L1,L2,L3,M1,M2'
 UNION ALL SELECT 'EGCGN','TECHNA',NULL,'GN','L1,L2,L3,M1,M2' UNION ALL SELECT 'EGCGN','TAN',NULL,'GN','L1,L2,L3,M1,M2') v ON v.k=e.code;
